-- 576: Original BrillaPrep WASSCE English Language sprint 3 beta questions, part 6 of 9 (batch wassce-english-sprint3-001).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_576_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_576_guard;
INSERT INTO _migration_576_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_018' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A candidate is arguing against the motion "Homework should be abolished". Which sentence would best open a body paragraph of the essay?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Homework is a common English word.","B. Homework burdens students who already spend long hours in the classroom.","C. Let me tell you about my school.","D. In conclusion, homework should be abolished."]' AND q.correct_answer IS 'B' AND q.explanation IS 'A body paragraph opens with a clear point supporting the writer''s side; the correct option states one argument, while the others are empty, irrelevant or a misplaced conclusion. Therefore the correct answer is B: Homework burdens students who already spend long hours in the classroom..' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_018' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_576_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_024' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_sum' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'When the two points required by a summary question come from different paragraphs of the passage, the candidate should' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. answer only the point in the first paragraph","B. skip the question entirely","C. copy both paragraphs in full","D. find and combine both points as the question demands"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The question, not the paragraph layout, controls the answer: both points must be located wherever they occur and combined; partial answers and copying lose marks. Therefore the correct answer is D: find and combine both points as the question demands.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_024' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_576_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_029' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_sum' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A summary question asks for "one cause of the strike" from a passage that mentions low pay, poor ventilation and long hours. A candidate writes: "The workers were unhappy about many things." The answer is weak mainly because it' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. names no specific cause from the passage","B. is too short to earn marks","C. contains a grammatical error","D. uses the candidate''s own words"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The question demands one identified cause; gesturing at "many things" names neither low pay, poor ventilation nor long hours, so it earns nothing despite being brief and grammatical. Therefore the correct answer is A: names no specific cause from the passage.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_029' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_576_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_030' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_sum' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which single sentence best combines the points "The bridge collapsed" and "The floods had weakened its pillars"?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The bridge collapsed and the floods.","B. The bridge collapsed because the floods had weakened its pillars.","C. The floods weakened the pillars after the bridge collapsed.","D. The bridge, the floods and the pillars."]' AND q.correct_answer IS 'B' AND q.explanation IS 'The correct option links the points causally and keeps the tense order — the weakening came before the collapse; the others are fragments or reverse the sequence of events. Therefore the correct answer is B: The bridge collapsed because the floods had weakened its pillars..' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Summarize' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_030' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_576_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_033' AND NOT (q.topic_id IS 'topic_wassce_english_essay' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is the best topic sentence for a paragraph on the causes of road accidents in an expository essay?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Road accidents are terrible events.","B. I once saw an accident near our house.","C. In conclusion, road accidents must stop.","D. One major cause of road accidents is over-speeding by drivers."]' AND q.correct_answer IS 'D' AND q.explanation IS 'A topic sentence states the paragraph''s single controlling idea; the correct option names one cause to develop, while the others are vague, anecdotal or a misplaced conclusion. Therefore the correct answer is D: One major cause of road accidents is over-speeding by drivers..' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_033' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
